import { localShellTool } from "@kybernesis/local";

// The user's OWN machine, reached through KYBER Studio. Studio holds an
// outbound connection to the control plane; these tools queue work on it and
// wait for the answer, so nothing here connects to anything and no port opens.
//
// Consent lives on the desktop, per EFFECT rather than per tool: run-command,
// read-file, write-file, list-directory. local_edit declares write-file and
// local_search declares read-file for exactly that reason — two tools reaching
// the same effect must not need two approvals, and must not be able to dodge
// one.
//
// Sibling files: local_read.ts, local_list.ts, local_search.ts, local_edit.ts,
// local_write.ts. Add only the ones this agent should have.
export default localShellTool();

import { localReadTool } from "@kybernesis/local";

// Read a file from the user's machine.
export default localReadTool();

import { localListTool } from "@kybernesis/local";

// List a directory on the user's machine.
export default localListTool();

import { localSearchTool } from "@kybernesis/local";

// Search file contents on the user's machine. Declares the read-file effect.
export default localSearchTool();

import { localEditTool } from "@kybernesis/local";

// Replace exact text in a file. Declares the write-file effect — same consequence as writing, so the same consent.
export default localEditTool();

import { localWriteTool } from "@kybernesis/local";

// Write a file on the user's machine.
export default localWriteTool();

import { localMcpTools } from "@kybernesis/local";

// Tools from MCP servers running on the user's OWN computer, reached through
// KYBER Studio's outbound connection.
//
// This is the case a hosted connector cannot cover: a database inside a company
// network, a private repository, an internal API with no ingress. The desktop
// dials out, so nothing has to be exposed to reach it.
//
// Nothing here when the user has no servers set up, or when their desktop is
// closed — a closed laptop means no local tools this turn, not a failed turn.
export default localMcpTools();
